//! # `ResNeSt` prefabs

// The prefabs and the stage table between the `gen_resnet_kin_prefabs`
// markers are generated by `tools/gen_resnet_kin_prefabs.py` from timm's own
// `resnest.py` entrypoints and models; edit the script, not them.

use alloc::{
    vec,
    vec::Vec,
};

use crate::{
    data::pretrained::{
        PrefabTable,
        Prefabs,
    },
    kits::images::classification::{
        resnest::ResNeStContractConfig,
        resnet::{
            BottleneckPolicyConfig,
            ResNetContractConfig,
            ResNetStemKind,
        },
    },
};

impl ResNeStContractConfig {
    /// A `ResNeSt` of 1000 classes: `ResNet` bottleneck stages of `layers`
    /// units, `base_width` channels per 64 planes in `cardinality` groups,
    /// `radix` splits, and the `avd` pool after the mixer, or before it under
    /// `avd_first`.
    fn resnest(
        layers: Vec<usize>,
        base_width: usize,
        cardinality: usize,
        radix: usize,
        avd_first: bool,
    ) -> Self {
        Self::new(
            ResNetContractConfig::new(layers, 1000).with_bottleneck_policy(Some(
                BottleneckPolicyConfig::new()
                    .with_base_width(base_width)
                    .with_cardinality(cardinality),
            )),
        )
        .with_radix(radix)
        .with_avd_first(avd_first)
    }

    /// This on timm's `deep` stem of `stem_width`, its shortcuts pooled
    /// (`avg_down`) as `avg_down` says.
    fn with_deep_stem(
        self,
        stem_width: usize,
        avg_down: bool,
    ) -> Self {
        Self {
            resnet: self
                .resnet
                .with_stem_type(ResNetStemKind::Deep)
                .with_stem_width(stem_width)
                .with_avg_down(avg_down),
            ..self
        }
    }

    // gen_resnet_kin_prefabs: begin fns
    /// The `resnest14d` prefab: `ResNeSt` `resnest14d`; radix 2, the `deep`
    /// stem of 32, average-pool shortcuts.
    pub fn resnest14d() -> Self {
        Self::resnest(vec![1, 1, 1, 1], 64, 1, 2, false).with_deep_stem(32, true)
    }

    /// The `resnest26d` prefab: `ResNeSt` `resnest26d`; radix 2, the `deep`
    /// stem of 32, average-pool shortcuts.
    pub fn resnest26d() -> Self {
        Self::resnest(vec![2, 2, 2, 2], 64, 1, 2, false).with_deep_stem(32, true)
    }

    /// The `resnest50d` prefab: `ResNeSt` `resnest50d`; radix 2, the `deep`
    /// stem of 32, average-pool shortcuts.
    pub fn resnest50d() -> Self {
        Self::resnest(vec![3, 4, 6, 3], 64, 1, 2, false).with_deep_stem(32, true)
    }

    /// The `resnest50d_1s4x24d` prefab: `ResNeSt` `resnest50d_1s4x24d`; radix
    /// 1, 4 groups of 24 per 64 planes, the `avd` pool before the mixer, the
    /// `deep` stem of 32, average-pool shortcuts.
    pub fn resnest50d_1s4x24d() -> Self {
        Self::resnest(vec![3, 4, 6, 3], 24, 4, 1, true).with_deep_stem(32, true)
    }

    /// The `resnest50d_4s2x40d` prefab: `ResNeSt` `resnest50d_4s2x40d`; radix
    /// 4, 2 groups of 40 per 64 planes, the `avd` pool before the mixer, the
    /// `deep` stem of 32, average-pool shortcuts.
    pub fn resnest50d_4s2x40d() -> Self {
        Self::resnest(vec![3, 4, 6, 3], 40, 2, 4, true).with_deep_stem(32, true)
    }

    /// The `resnest101e` prefab: `ResNeSt` `resnest101e`; radix 2, the `deep`
    /// stem of 64, average-pool shortcuts.
    pub fn resnest101e() -> Self {
        Self::resnest(vec![3, 4, 23, 3], 64, 1, 2, false).with_deep_stem(64, true)
    }

    /// The `resnest200e` prefab: `ResNeSt` `resnest200e`; radix 2, the `deep`
    /// stem of 64, average-pool shortcuts.
    pub fn resnest200e() -> Self {
        Self::resnest(vec![3, 24, 36, 3], 64, 1, 2, false).with_deep_stem(64, true)
    }

    /// The `resnest269e` prefab: `ResNeSt` `resnest269e`; radix 2, the `deep`
    /// stem of 64, average-pool shortcuts.
    pub fn resnest269e() -> Self {
        Self::resnest(vec![3, 30, 48, 8], 64, 1, 2, false).with_deep_stem(64, true)
    }
    // gen_resnet_kin_prefabs: end fns
}

/// The `ResNeSt` geometries by name, timm's architecture names: a
/// [`ResNeStContractConfig`] of 1000 classes for every architecture of
/// timm's `resnest.py` with hub weights.
///
/// A prefab has no weights: a timm row takes the classes from its
/// `config.json`.
impl Prefabs for ResNeStContractConfig {
    const PREFABS: PrefabTable<Self> = &[
        // gen_resnet_kin_prefabs: begin table
        ("resnest14d", Self::resnest14d),
        ("resnest26d", Self::resnest26d),
        ("resnest50d", Self::resnest50d),
        ("resnest50d_1s4x24d", Self::resnest50d_1s4x24d),
        ("resnest50d_4s2x40d", Self::resnest50d_4s2x40d),
        ("resnest101e", Self::resnest101e),
        ("resnest200e", Self::resnest200e),
        ("resnest269e", Self::resnest269e),
        // gen_resnet_kin_prefabs: end table
    ];
    const PREFAB_TABLE: &'static str = "resnest";
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        blocks::{
            conv::ConvBlock2dMeta,
            images::models::conv_net::ConvChainMeta,
        },
        burner::module::ToStructureConfig,
    };

    /// Each architecture as timm builds it: its stem's conv widths, and each
    /// stage's `(depth, width, mixer width)`, read from timm's modules (the
    /// mixer width is the first `1x1`'s output).
    #[allow(clippy::type_complexity)]
    const TIMM_STAGES: &[(&str, &[usize], [(usize, usize, usize); 4])] = &[
        // gen_resnet_kin_prefabs: begin stages
        (
            "resnest14d",
            &[32, 32, 64],
            [(1, 256, 64), (1, 512, 128), (1, 1024, 256), (1, 2048, 512)],
        ),
        (
            "resnest26d",
            &[32, 32, 64],
            [(2, 256, 64), (2, 512, 128), (2, 1024, 256), (2, 2048, 512)],
        ),
        (
            "resnest50d",
            &[32, 32, 64],
            [(3, 256, 64), (4, 512, 128), (6, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnest50d_1s4x24d",
            &[32, 32, 64],
            [(3, 256, 96), (4, 512, 192), (6, 1024, 384), (3, 2048, 768)],
        ),
        (
            "resnest50d_4s2x40d",
            &[32, 32, 64],
            [(3, 256, 80), (4, 512, 160), (6, 1024, 320), (3, 2048, 640)],
        ),
        (
            "resnest101e",
            &[64, 64, 128],
            [(3, 256, 64), (4, 512, 128), (23, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnest200e",
            &[64, 64, 128],
            [
                (3, 256, 64),
                (24, 512, 128),
                (36, 1024, 256),
                (3, 2048, 512),
            ],
        ),
        (
            "resnest269e",
            &[64, 64, 128],
            [
                (3, 256, 64),
                (30, 512, 128),
                (48, 1024, 256),
                (8, 2048, 512),
            ],
        ),
        // gen_resnet_kin_prefabs: end stages
    ];

    /// Every prefab's stem and stages are timm's.
    #[test]
    fn test_prefab_stages_are_timms() {
        assert_eq!(
            TIMM_STAGES.len(),
            ResNeStContractConfig::prefab_names().len()
        );
        for (name, stem, stages) in TIMM_STAGES {
            let structure = ResNeStContractConfig::expect_prefab(name)
                .try_to_structure()
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            let ours: Vec<_> = structure
                .stem
                .convs
                .iter()
                .map(|c| c.out_channels())
                .collect();
            assert_eq!(&ours, stem, "{name}: the stem");
            let ours: Vec<_> = structure
                .stages
                .iter()
                .map(|s| {
                    let unit = &s.units[0];
                    (
                        s.units.len(),
                        unit.out_channels(),
                        unit.convs[0].out_channels(),
                    )
                })
                .collect();
            assert_eq!(ours, stages, "{name}");
        }
    }
}
